                return [
                    [2 if a != 0 and b != 0 else 0 for a, b in zip(row1, row2)]
                    for row1, row2 in zip(top, bottom)
                ]

    for c in range(w):
        if len({grid[r][c] for r in range(h)}) == 1 and (c % 2 == 0):
            left = [row[:c] for row in grid]
            right = [row[c + 1:] for row in grid]
            if all(len(a) == len(b) for a, b in zip(left, right)):
                return [
                    [2 if a != 0 and b != 0 else 0 for a, b in zip(row1, row2)]
                    for row1, row2 in zip(left, right)
                ]

